240	// count written (0 on failure or NULL handle). Used for vector regs whose
241	// width = vlenb bytes.
242	static size_t read_reg_bytes(struct qemu_plugin_register *h,
243	                             uint8_t *dst, size_t dst_max)
244	{
245	    if (!h || dst_max == 0) return 0;
246	    g_autoptr(GByteArray) buf = g_byte_array_new();
247	    int sz = qemu_plugin_read_register(h, buf);
248	    if (sz <= 0) return 0;
249	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
250	    memcpy(dst, buf->data, n);
