254	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
255	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
256	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
257	// collide even under aggressive PID reuse (B13). The tmp lives in the
258	// same directory as `path` so the rename is intra-filesystem.
259	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
260	{
261	    char tmp[PATH_MAX];
262	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
263	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
264	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
265	        return -1;
266	    }
267	    int fd = g_mkstemp(tmp);
268	    if (fd < 0) {
269	        perror("hybrid_handoff: g_mkstemp");
270	        return -1;
271	    }
272	    // g_mkstemp creates the file 0600; no further chmod needed.
273	    ssize_t want = (ssize_t) sizeof(*s);
274	    ssize_t got = write(fd, s, sizeof(*s));
275	    if (got != want) {
276	        perror("hybrid_handoff: write");
277	        close(fd);
278	        unlink(tmp);
279	        return -1;
280	    }
281	    fsync(fd);
282	    close(fd);
283	    if (rename(tmp, path) != 0) {
284	        perror("hybrid_handoff: rename");
285	        unlink(tmp);
286	        return -1;
287	    }
288	    return 0;
289	}
