299	    resolve_handles(v);
300	    memset(sp, 0, sizeof(*sp));
301	    struct hybrid_state_v1 s = {0};
302	    s.magic   = HYBRID_STATE_MAGIC;
303	    s.version = HYBRID_STATE_VERSION;
304	    s.flags   = HYBRID_FLAG_RV64;
305	    s.hart_id = vcpu_idx;
306	    // L6: real privilege at the boundary; M-mode fallback only when the
307	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
308	    // reads as 0 = U, which would silently demote the hart).
309	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
310	    s.pc      = pc;
311	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
312	
313	    // Floating-point: only set FP flag if at least one handle was bound,
314	    // i.e. QEMU advertised the FPU feature (D extension).
315	    int has_fp = 0;
316	    for (int i = 0; i < 32; i++) {
317	        s.fpr[i] = read_reg64(v->fpr[i]);
318	        if (v->fpr[i]) has_fp = 1;
319	    }
320	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
321	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
322	
323	    s.mstatus  = read_reg64(v->mstatus);
324	    s.mepc     = read_reg64(v->mepc);
325	    s.mtvec    = read_reg64(v->mtvec);
326	    s.mcause   = read_reg64(v->mcause);
327	    s.mtval    = read_reg64(v->mtval);
328	    s.mscratch = read_reg64(v->mscratch);
329	    s.medeleg  = read_reg64(v->medeleg);
330	    s.mideleg  = read_reg64(v->mideleg);
331	    s.mip      = read_reg64(v->mip);
332	    s.mie      = read_reg64(v->mie);
333	    s.mcycle   = read_reg64(v->mcycle);
334	    s.minstret = minstret_override ? minstret_override
335	                                   : read_reg64(v->minstret);
336	    s.satp     = read_reg64(v->satp);
337	
338	    // Andes cache fix: carry crt0's cache-enable so the cycle engine resumes
339	    // with caches on (NULL handle on a non-Andes stub reads back as 0).
340	    s.mcache_ctl = read_reg64(v->mcache_ctl);
341	    s.mmisc_ctl  = read_reg64(v->mmisc_ctl);
342	
343	    // Andes V5 CSR block (v3): drain every transported Andes CSR. Set
344	    // HYBRID_FLAG_ANDES if the stub advertised at least one (mirrors has_fp/
345	    // has_v); otherwise the block stays zero and consumers skip it. A NULL
346	    // handle on a non-Andes stub reads back as 0 -> tolerant.
347	    int has_andes = 0;
348	#define HYBRID_ANDES_FIELD(field, addr, name)  \
349	    s.andes.field = read_reg64(v->andes_##field); \
350	    if (v->andes_##field) has_andes = 1;
351	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
352	#undef HYBRID_ANDES_FIELD
353	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
354	        s.andes.pmacfg[i] = read_reg64(v->pmacfg[i]);
355	        if (v->pmacfg[i]) has_andes = 1;
356	    }
357	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
358	        s.andes.pmaaddr[i] = read_reg64(v->pmaaddr[i]);
359	        if (v->pmaaddr[i]) has_andes = 1;
360	    }
361	    if (has_andes) s.flags |= HYBRID_FLAG_ANDES;
362	
363	    // M-ext CSR block (v4): drain every transported M-mode CSR the stub
364	    // advertised. Set HYBRID_FLAG_M_EXT if at least one resolved; a NULL handle
365	    // reads 0. The vsim caps gate decides which of these the cycle engine
366	    // actually restores, so draining an absent-on-vsim CSR here is harmless.
367	    int has_m_ext = 0;
368	#define HYBRID_M_EXT_FIELD(field, addr, name)  \
369	    s.m_ext.field = read_reg64(v->m_ext_##field); \
370	    if (v->m_ext_##field) has_m_ext = 1;
371	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
372	#undef HYBRID_M_EXT_FIELD
373	    if (has_m_ext) s.flags |= HYBRID_FLAG_M_EXT;
374	
375	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
376	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
377	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
378	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
379	
380	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
381	    // bounds the per-register byte count copied into vreg[]. The policy
382	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
383	    // handle truthiness so we don't conflate "stub missing vlenb" with
384	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
385	    s.vstart = read_reg64(v->vstart);
386	    s.vxsat  = read_reg64(v->vxsat);
387	    s.vxrm   = read_reg64(v->vxrm);
388	    s.vcsr   = read_reg64(v->vcsr);
389	    s.vtype  = read_reg64(v->vtype);
390	    s.vl     = read_reg64(v->vl);
391	    s.vlenb  = read_reg64(v->vlenb);
392	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
393	                       || v->vtype || v->vl);
394	    if (!has_other_v) {
395	        for (int i = 0; i < 32; i++)
396	            if (v->vreg[i]) { has_other_v = 1; break; }
397	    }
398	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
399	        v->vlenb != NULL, has_other_v, s.vlenb);
400	    if (vpol == HYBRID_V_DRAIN_ABORT) {
401	        if (v->vlenb == NULL)
402	            fprintf(stderr,
403	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
404	                    "vlenb; refusing to drain partial V state\n");
405	        else
406	            fprintf(stderr,
407	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
408	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
409	                    "truncate V registers\n",
410	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
411	                    8 * HYBRID_VLEN_BYTES_MAX);
412	        exit(2);
413	    }
414	    if (vpol == HYBRID_V_DRAIN_OK) {
415	        s.flags |= HYBRID_FLAG_V;
416	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
417	         * full live register fits the wire-format slot -- no clamp (L11). */
418	        for (int i = 0; i < 32; i++)
419	            (void) read_reg_bytes(v->vreg[i],
420	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
421	                                  (size_t) s.vlenb);
422	    }
423	
424	    // v6: which mask-governed CSRs the guest actually wrote (translate-time
425	    // decode + exec callbacks above). ucode rides transport-always: DSP
426	    // instructions update its sticky OV flag without any CSR instruction, so
427	    // instruction-level tracking cannot see those writes (like fcsr's fflags).
428	    s.write_mask[0] = __atomic_load_n(&csr_write_mask[0], __ATOMIC_RELAXED);
429	    s.write_mask[1] = __atomic_load_n(&csr_write_mask[1], __ATOMIC_RELAXED);
430	    hybrid_wm_set(s.write_mask, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_ucode);
431	    s.flags |= HYBRID_FLAG_WRITE_MASK;
432	
433	    // v5: L2C MMIO register window (DS220 11.8.5 Table 112, offsets
434	    // 0x0000..0x0527). Read the whole documented block from the L2C base by
435	    // PHYSICAL address (paging is off in the M-mode boot flow, so VA==PA anyway).
436	    // QEMU's AE350 machine maps L2C as a device region; if the read fails (a
437	    // machine without an L2C), the flag stays clear and consumers skip the
438	    // block. Little-endian native host, so the raw bytes land directly in
439	    // s.l2c.reg[]. The vsim side gates restore on its OWN L2C presence, so
440	    // setting the flag whenever QEMU can read the region is correct.
441	    {
442	        g_autoptr(GByteArray) l2c = g_byte_array_new();
443	        enum qemu_plugin_hwaddr_operation_result r =
444	            qemu_plugin_read_memory_hwaddr(l2c_base_arg, l2c,
445	                                           HYBRID_L2C_REG_WINDOW_BYTES);
446	        if (r == QEMU_PLUGIN_HWADDR_OPERATION_OK
447	            && l2c->len == HYBRID_L2C_REG_WINDOW_BYTES) {
448	            memcpy(s.l2c.reg, l2c->data, HYBRID_L2C_REG_WINDOW_BYTES);
449	            s.flags |= HYBRID_FLAG_L2C;
450	        }
451	    }
452	
453	    *sp = s;
454	}
455	
456	// Drain CPU state to `path`. Does NOT call exit -- the caller decides
457	// exit(200).
458	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
459	                                uint64_t minstret_override, const char *path)
460	{
461	    struct hybrid_state_v1 s;
462	    drain_state_into(vcpu_idx, pc, minstret_override, &s);
463	    if (write_state_atomic(&s, path) != 0) {
464	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
465	        exit(2);
466	    }
467	    fprintf(stderr,
468	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 ")\n",
469	            path, s.pc);
470	}
471	
472	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
473	// as the vsim resume point, and exit 200.
474	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
475	{
476	    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
477	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
478	    // Distinguishes drain from workload completion (0) so the orchestrator
479	    // can decide the next spawn.
480	    exit(200);
481	}
482	
483	// Marker sites. The marker is an architectural NOP, so the pre-execution
484	// state equals the post-retire state and the window resumes AFTER it
485	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
486	// the exec callback can lag the actual current insn when V instructions
487	// retire just before the trigger -- TCG defers PC writes for performance).
488	static void on_handoff(unsigned int vcpu_idx, void *udata)
489	{
490	    const HandoffSite *site = (const HandoffSite *) udata;
491	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
492	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
493	}
494	
495	// pc boundary sites. Exec callbacks fire BEFORE the insn
496	// executes, and the boundary insn is real user code (unlike a marker NOP):
497	// the drained state must resume AT the boundary so the insn executes inside
498	// the vsim window rather than on neither leg. (Skipping it corrupts the
499	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
500	// set and the first vector op of the window faults.)
501	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
502	{
503	    const HandoffSite *site = (const HandoffSite *) udata;
504	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
505	    handoff_drain(vcpu_idx, site->vaddr);
506	}
507	
508	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
509	// When armed (the exit boundary's own tick ran), this tick fires before its
510	// insn executes, so a drain here records the post-retire state of the
511	// boundary insn with pc = the dynamically-next insn's vaddr.
512	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
513	{
514	    const HandoffSite *site = (const HandoffSite *) udata;
515	    if (oracle_armed
516	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
517	        handoff_drain(vcpu_idx, site->vaddr);
518	    }
519	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
520	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
521	        oracle_armed = 1;
522	    }
523	}
524	
525	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
526	{
527	    (void) id;
528	    size_t n = qemu_plugin_tb_n_insns(tb);
529	
530	    for (size_t i = 0; i < n; i++) {
531	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
532	
533	        // v6: CSR write-mask tracking, active in every trigger mode (the mode
534	        // branches below `continue`). Decoded once at translation; only an
535	        // instruction that writes a mask-governed CSR gets an exec callback
536	        // (the CSR address is a static field of the encoding), so this costs
537	        // nothing at execution time outside boot-style CSR setup code. No
538	        // compressed CSR instruction exists, so the size==4 gate is exact.
539	        if (qemu_plugin_insn_size(insn) == 4) {
540	            uint32_t w = 0;
541	            if (qemu_plugin_insn_data(insn, &w, sizeof(w)) == sizeof(w)) {
542	                const int slot = hybrid_wm_slot_for_insn(w);
543	                if (slot >= 0)
544	                    qemu_plugin_register_vcpu_insn_exec_cb(
545	                        insn, on_csr_write, QEMU_PLUGIN_CB_NO_REGS,
546	                        (void *) (uintptr_t) slot);
547	            }
548	        }
549	
550	        // Oracle exit-drain mode: exclusive with every other mode (enforced
551	        // at install), so it owns the insn's registration outright. The site
552	        // carries the marker kind so the tick can arm on the EXIT marker.
553	        if (exit_marker_mode || exit_pc_mode) {
554	            HandoffSite *site = g_new0(HandoffSite, 1);
555	            site->kind  = HYBRID_HANDOFF_NONE;
556	            site->vaddr = qemu_plugin_insn_vaddr(insn);
557	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
558	            if (exit_marker_mode && site->size == 4) {
559	                uint32_t raw = 0;
560	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
561	                    hybrid_match_handoff_insn(raw, &site->kind);
562	            }
563	            qemu_plugin_register_vcpu_insn_exec_cb(
564	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
565	            continue;
566	        }
567	
568	        if (pc_mode) {
569	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
570	            // boundary (on_handoff_boundary), so the insn size is recorded
571	            // only for completeness.
572	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
573	            HandoffSite *site = g_new0(HandoffSite, 1);
574	            site->kind  = HYBRID_HANDOFF_ENTER;
575	            site->vaddr = qemu_plugin_insn_vaddr(insn);
576	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
577	            qemu_plugin_register_vcpu_insn_exec_cb(
578	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
579	            continue;
580	        }
581	
582	        // Marker-trigger mode (default).
583	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
584	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
585	        // exact, not an approximation.
586	        size_t sz = qemu_plugin_insn_size(insn);
587	        if (sz != 4) continue;
588	        uint32_t raw = 0;
589	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
590	            continue;
591	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
592	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
593	        HandoffSite *site = g_new0(HandoffSite, 1);
594	        site->kind  = kind;
595	        site->vaddr = qemu_plugin_insn_vaddr(insn);
596	        site->size  = (uint32_t) sz;
597	        qemu_plugin_register_vcpu_insn_exec_cb(
598	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
599	    }
600	}
601	
602	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
603	                                           const qemu_info_t *info,
604	                                           int argc, char **argv)
605	{
606	    (void) info;
607	    for (int i = 0; i < argc; i++) {
608	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
609	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
610	            outfile_path = g_strdup(tok[1]);
611	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
612	            char *endp = NULL;
613	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
614	            if (!endp || *endp != '\0') {
615	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
616	                        tok[1]);
617	                return -1;
618	            }
619	            enter_pc_arg = (uint64_t) v;
620	            pc_mode = 1;
621	        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
622	            char *endp = NULL;
623	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
624	            if (!endp || *endp != '\0') {
625	                fprintf(stderr, "hybrid_handoff: invalid exit_pc=%s\n",
626	                        tok[1]);
627	                return -1;
628	            }
629	            exit_pc_arg = (uint64_t) v;
630	            exit_pc_mode = 1;
631	        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
632	            char *endp = NULL;
633	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
634	            if (!endp || *endp != '\0') {
635	                fprintf(stderr, "hybrid_handoff: invalid exit_marker=%s\n",
636	                        tok[1]);
637	                return -1;
638	            }
639	            exit_marker_mode = (v != 0);
640	        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
641	            char *endp = NULL;
642	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
643	            if (!endp || *endp != '\0') {
644	                fprintf(stderr, "hybrid_handoff: invalid drain_pc=%s\n",
645	                        tok[1]);
646	                return -1;
647	            }
648	            drain_pc_arg = (uint64_t) v;
649	            drain_pc_set = 1;
650	        } else if (g_strcmp0(tok[0], "l2c_base") == 0 && tok[1]) {
651	            char *endp = NULL;
652	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
653	            if (!endp || *endp != '\0') {
654	                fprintf(stderr, "hybrid_handoff: invalid l2c_base=%s\n",
655	                        tok[1]);
656	                return -1;
657	            }
658	            l2c_base_arg = (uint64_t) v;
659	        } else {
660	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
661	            return -1;
662	        }
663	    }
664	    if (!outfile_path) {
665	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
666	        return -1;
667	    }
668	    if (pc_mode) {
669	        fprintf(stderr,
670	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
671	                enter_pc_arg);
672	    }
673	    if (exit_marker_mode || exit_pc_mode) {
674	        if ((exit_marker_mode && exit_pc_mode) || pc_mode) {
675	            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
676	                  "is exclusive with the other trigger modes\n", stderr);
677	            return -1;
678	        }
679	        if (exit_pc_mode) {
680	            fprintf(stderr,
681	                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
682	                    PRIx64 "\n", exit_pc_arg);
683	        } else {
684	            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
685	                  stderr);
686	        }
687	        if (drain_pc_set) {
688	            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
689	                    drain_pc_arg);
690	        }
691	    } else if (drain_pc_set) {
692	        fputs("hybrid_handoff: drain_pc requires oracle exit-drain mode "
693	              "(exit_marker/exit_pc)\n", stderr);
694	        return -1;
695	    }
696	
697	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
698	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
699	    return 0;
700	}
701

