/* F2 debug probe (not committed): discriminate WHY the hart-local ILM read
 * misses after --ilm.
 *   exit 5: milmb.EN == 0 at RTL reset (hart-local view disabled)
 *   exit 6: slave-port read misses too -> set_ilm poke wiped / wrong array
 *   exit 1: slave-port sees it, hart-local does not -> local-view routing
 *   exit 0: both views see the pattern
 */
#include <stdint.h>

#define RD(a) (*(volatile uint32_t *)(uintptr_t)(a))

int main(void)
{
  uint64_t milmb;
  __asm__ volatile("csrr %0, 0x7c0" : "=r"(milmb));
  if (!(milmb & 1)) return 5;
  if (RD(0xA0000010u) != 0x494C4D30u) return 6;
  if (RD(0x000010u)   != 0x494C4D30u) return 1;
  return 0;
}

