 *
 *   - the HART-LOCAL view (premium geometry: ILM 0x0..0xFFFF 64KB,
 *     DLM 0x200000..0x207FFF 32KB) -- the core's internal TCM path;
 *   - the LOCAL MEMORY SLAVE PORT aperture (HART0_ILM_BASE 0xA0000000,
 *     HART0_DLM_BASE 0xA0200000): a hart load there goes OUT the bus
 *     master port, through the interconnect route {HART0_ILM_BASE,
 *     HART0_DLM_END} -> slv_bfm, and back into the same SRAM -- the only
 *     test that exercises the vsim slave-port routing at all (the
 *     transport itself is backdoor pokes on this side, and the ROI
 *     fixtures use the local view).
 *
 * The ILM head probes sit at +0x10, not +0, so no pointer is the C NULL
 * address. Exit code names the first failure; 0 = all eight words intact.
 * The same binary doubles as the negative control: with no --ilm/--dlm the
 * TCM is reset-empty and this exits nonzero. */
#include "runtime/rt_c_helpers.h"
#include "runtime/memory_map.h"

#include <stdint.h>

#define RD(a) (*(volatile uint32_t *)(uintptr_t)(a))

int main(void)
{
  uint64_t v;
  enable_ilm();
  enable_dlm();

  __asm__ volatile("csrr %0, 0x7c0" : "=r"(v));
  if (!(v & 1)) return 5;                       /* EN write did not stick */

  /* Hart-local view. */
  if (RD(0x000010u) != 0x494C4D30u) return 1;   /* ILM head ("ILM0") */
  if (RD(0x00FFFCu) != 0x494C4D31u) return 2;   /* ILM tail ("ILM1") */
  if (RD(0x200000u) != 0x444C4D30u) return 3;   /* DLM head ("DLM0") */
  if (RD(0x207FFCu) != 0x444C4D31u) return 4;   /* DLM tail ("DLM1") */

  /* Slave-port aperture: same words, routed hart -> bus -> slv port. */
  if (RD(HART0_ILM_BASE + 0x0010u) != 0x494C4D30u) return 6;
  if (RD(HART0_ILM_BASE + 0xFFFCu) != 0x494C4D31u) return 7;
  if (RD(HART0_DLM_BASE + 0x0000u) != 0x444C4D30u) return 8;
  if (RD(HART0_DLM_BASE + 0x7FFCu) != 0x444C4D31u) return 9;
  return 0;
}

